import assert from 'node:assert/strict';
import {readdir,readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import sharp from '/private/tmp/zellij-rc7-preparation/node_modules/sharp/dist/index.mjs';
const baseline='/private/tmp/zellij-rc9-source-pdfs',current='/private/tmp/zellij-print-style-pdfs';
async function files(root,prefix='') {const out=[];for(const d of await readdir(path.join(root,prefix),{withFileTypes:true})){const p=path.join(prefix,d.name);if(d.isDirectory())out.push(...await files(root,p));else out.push(p);}return out;}
let tex=0,pages=0;
for(const name of await files(baseline)) {
 if(name.endsWith('book.tex')) {assert((await readFile(path.join(baseline,name))).equals(await readFile(path.join(current,name))),name);tex++;}
 if(/page-\d+\.png$/.test(name)) {const [a,b]=await Promise.all([baseline,current].map(dir=>sharp(path.join(dir,name)).ensureAlpha().raw().toBuffer({resolveWithObject:true})));assert.deepEqual(a.info,b.info,name);assert(a.data.equals(b.data),name);pages++;}
}
assert.equal(tex,30);assert.equal(pages,312);
const names=await files(current);const customs=names.filter(n=>n.includes('-custom/')&&/page-\d+\.png$/.test(n));
// All three native runtimes and both Next architectures typeset the same styled technical manuscript.
for (const edition of ['technical','study']) for(const folder of ['book-pdf-ubuntu-latest-podman','book-pdf-ubuntu-24.04-arm-docker',...(edition==='technical'?['next-pdf-ubuntu-latest','next-pdf-ubuntu-24.04-arm']:[])]) {
 const a=path.join(current,'book-pdf-ubuntu-latest-docker',edition+'-custom'),b=path.join(current,folder,edition+'-custom');
 const receiptA=JSON.parse(await readFile(path.join(a,'pdf.json'))),receiptB=JSON.parse(await readFile(path.join(b,'pdf.json')));
 assert.equal(receiptA.revision,receiptB.revision);
 const {enabled: aEnabled,...aPrint}=receiptA.settings,{enabled:bEnabled,...bPrint}=receiptB.settings;
 assert.equal(aEnabled,false);assert.equal(bEnabled,folder.startsWith('next-pdf'));assert.deepEqual(aPrint,bPrint);
 assert((await readFile(path.join(a,'text.txt'))).equals(await readFile(path.join(b,'text.txt'))),folder+' text');
 const images=(await files(a)).filter(n=>/^page-\d+\.png$/.test(n));assert.deepEqual(images.sort(),(await files(b)).filter(n=>/^page-\d+\.png$/.test(n)).sort());
 for(const name of images) {const [x,y]=await Promise.all([a,b].map(dir=>sharp(path.join(dir,name)).ensureAlpha().raw().toBuffer({resolveWithObject:true})));assert.deepEqual(x.info,y.info);assert(x.data.equals(y.data),folder+'/'+name);}
}
const result={baseline:'reviewed rc.9 source PDFs, same runtime/architecture',unchanged_tex:tex,unchanged_pages:pages,total_pdfs:names.filter(n=>/\bbook\.pdf$/.test(n)).length,new_styled_pages:customs.length,styled_technical_native_next_runtimes_match:true,styled_study_native_runtimes_match:true};
await writeFile('/private/tmp/zellij-print-style-pdf-comparison.json',JSON.stringify(result,null,2)+'\n');console.log(result);
